namespace EmpireSim.Core.Models;

/// <summary>
/// The flag of every country (code half; the drawings are in Flags.Data.cs, generated by tools/flags/make-flags.js). A flag is inline SVG: it cannot be
/// missing, broken or blurred, it has no letters in it, and it is drawn 3:2 so the main screen can show the middle of it in the round emblem
/// (<c>preserveAspectRatio="slice"</c>, never stretched). A country without a flag gets a neutral emblem, never its initials.
/// </summary>
public static partial class FlagCatalog
{
    /// <summary>The countries that have a flag.</summary>
    public static IReadOnlyCollection<string> Ids => Svgs.Keys;

    /// <summary>Whether a country has a flag of its own.</summary>
    public static bool Has(string? nationId) => nationId is not null && Svgs.ContainsKey(nationId);

    /// <summary>The flag of a country, or the neutral emblem when it has none.</summary>
    public static string Svg(string? nationId) => nationId is not null && Svgs.TryGetValue(nationId, out var svg) ? svg : FallbackSvg;
}
